1	import { createHash } from "node:crypto";
2	import { bareHost, siteHostAllowed } from "@/app/api/site/[slug]/site-host";
3	
4	// =============================================================================
5	// SHARED MACHINERY FOR "A PUBLISHED SITE POSTS SOMETHING BACK TO KODELY"
6	// =============================================================================
7	//
8	// Both lib/site-forms.ts (`POST /__forms/<name>`) and lib/site-records.ts
9	// (`POST /__records/<kind>`) are the same shape of hole in "generated sites
10	// have no backend": a same-origin `<form method="post">` navigation, landing
11	// on this app's own database, guarded by the same host/origin checks, the
12	// same body caps, and the same three-layer rate limiter. This file is ONLY
13	// the part that is genuinely identical between them - parsing field bodies,
14	// hashing IPs, bounding an in-process counter, building the HTML reply a
15	// browser navigation expects. Anything that differs (which model gets
16	// written, what the reply says, the exact rate-limit numbers) stays in the
17	// two callers.
18	
19	const SITES_BASE = (process.env.KODELY_SITES_BASE ?? "kodely.site").trim().toLowerCase();
20	
21	// -- Identifiers used in a URL path segment ----------------------------------
22	//
23	// A form name and a record kind are both "a short, boring, URL-safe word the
24	// builder chose", validated the same way for the same reason: it is stored
25	// and it is part of a public path, so it must never need escaping anywhere.
26	export const PATH_IDENTIFIER_RE = /^[a-z0-9][a-z0-9-]{0,31}$/;
27	
28	// -- Field bodies -------------------------------------------------------------
29	//
30	// The cap discipline from FormSubmission's original design, unchanged:
31	// stored fields are capped in count, key length and value length, and the
32	// combination cannot exceed what MAX_BODY_BYTES already refused to read past.
33	export const MAX_FIELDS = 12;
34	export const MAX_KEY_LENGTH = 64;
35	export const MAX_VALUE_LENGTH = 5000;
36	/** Field names the builder may emit. Rejecting anything else keeps the stored
37	 *  JSON's key space to identifiers, so no key can collide with object
38	 *  internals or need escaping anywhere downstream. */
39	export const FIELD_NAME_RE = /^[A-Za-z][A-Za-z0-9_-]{0,63}$/;
40	
41	// Control characters to strip from a submitted value, expressed via char
42	// codes rather than a \u escape literal in source so nothing downstream can
43	// mistake this for text that needs its own escaping: C0 controls other than
44	// the newline already normalised below, plus DEL.
45	const CONTROL_CHARS_RE = new RegExp(
46	  "[" +
47	    String.fromCharCode(0) +
48	    "-" +
49	    String.fromCharCode(8) +
50	    String.fromCharCode(11) +
51	    String.fromCharCode(12) +
52	    String.fromCharCode(14) +
53	    "-" +
54	    String.fromCharCode(31) +
55	    String.fromCharCode(127) +
56	    "]",
57	  "g",
58	);
59	
60	/** Collapse control characters, normalise newlines, trim. Never HTML-escapes:
61	 *  escaping belongs at each output boundary, not in storage, or the stored
62	 *  value stops being what the visitor typed. */
63	export function cleanValue(raw: string): string {
64	  return raw
65	    .replace(/\r\n?/g, "\n")
66	    .replace(CONTROL_CHARS_RE, "")
67	    .trim();
68	}
69	
70	export type ParsedBody =
71	  | { ok: true; fields: Record<string, string>; control: Record<string, string> }
72	  | { ok: false; status: number; message: string };
73	
74	/**
75	 * Parse an `application/x-www-form-urlencoded` body into stored fields and
76	 * `_`-prefixed control fields (the honeypot, the timing token, the post-submit
77	 * destination), applying the same caps FormSubmission has always used.
78	 */
79	export function parseFields(raw: string): ParsedBody {
80	  let params: URLSearchParams;
81	  try {
82	    params = new URLSearchParams(raw);
83	  } catch {
84	    return { ok: false, status: 400, message: "That could not be read." };
85	  }
86	
87	  const fields: Record<string, string> = {};
88	  const control: Record<string, string> = {};
89	  const seen = new Set<string>();
90	
91	  for (const key of params.keys()) {
92	    if (seen.has(key)) continue;
93	    seen.add(key);
94	
95	    if (key.length > MAX_KEY_LENGTH) {
96	      return { ok: false, status: 400, message: "That had an unexpected field." };
97	    }
98	
99	    // `_`-prefixed names are control fields: never stored, never emailed.
100	    if (key.startsWith("_")) {
101	      control[key] = cleanValue(params.get(key) ?? "").slice(0, 200);
102	      continue;
103	    }
104	
105	    if (!FIELD_NAME_RE.test(key)) {
106	      return { ok: false, status: 400, message: "That had an unexpected field." };
107	    }
108	
109	    // Repeated names (a checkbox group) collapse to one field, not many.
110	    const value = cleanValue(params.getAll(key).join(", "));
111	    if (value.length > MAX_VALUE_LENGTH) {
112	      return {
113	        ok: false,
114	        status: 413,
115	        message: `One of those answers is too long (${MAX_VALUE_LENGTH} characters max).`,
116	      };
117	    }
118	    if (value === "") continue;
119	
120	    if (Object.keys(fields).length >= MAX_FIELDS) {
121	      return { ok: false, status: 400, message: "That had too many fields." };
122	    }
123	    fields[key] = value;
124	  }
125	
126	  if (Object.keys(fields).length === 0) {
127	    return { ok: false, status: 400, message: "Please fill something in before sending it." };
128	  }
129	  return { ok: true, fields, control };
130	}
131	
132	// -- Body reading -------------------------------------------------------------
133	
134	/**
135	 * Read at most `maxBytes`, then stop.
136	 *
137	 * `await req.text()` would buffer whatever was sent, and Content-Length is a
138	 * claim by the caller, not a fact - so the length header is only used as a
139	 * fast pre-check and the stream is counted as it arrives. Returns null when
140	 * the cap is passed, and cancels the rest rather than draining it.
141	 */
142	export async function readCapped(req: Request, maxBytes: number): Promise<string | null> {
143	  const declared = Number(req.headers.get("content-length") ?? "");
144	  if (Number.isFinite(declared) && declared > maxBytes) return null;
145	
146	  const body = req.body;
147	  if (!body) return "";
148	
149	  const reader = body.getReader();
150	  const chunks: Buffer[] = [];
151	  let total = 0;
152	  let done = false;
153	  while (!done) {
154	    const next = await reader.read();
155	    done = next.done;
156	    if (next.value) {
157	      total += next.value.byteLength;
158	      if (total > maxBytes) {
159	        await reader.cancel().catch(() => undefined);
160	        return null;
161	      }
162	      chunks.push(Buffer.from(next.value));
163	    }
164	  }
165	  return Buffer.concat(chunks).toString("utf8");
166	}
167	
168	// -- IP handling ---------------------------------------------------------------
169	
170	/**
171	 * The client address, or the shared bucket for traffic that did not come
172	 * through the edge.
173	 *
174	 * Only `cf-connecting-ip` is trustworthy here. Cloudflare sets it on every
175	 * request, overwriting whatever the client sent. `x-forwarded-for`'s first
176	 * entry is attacker-chosen - Cloudflare APPENDS rather than replaces - so
177	 * keying on it hands an attacker a fresh bucket per request.
178	 *
179	 * No header => direct-to-origin or local dev => one shared, strict bucket.
180	 * Fails closed: such traffic is throttled collectively, never exempted.
181	 */
182	export function clientIp(req: Request): string {
183	  return req.headers.get("cf-connecting-ip")?.trim().toLowerCase() || "no-edge";
184	}
185	
186	/**
187	 * What actually gets stored against a row. A raw visitor IP is personal data
188	 * the site owner has no need for; a salted digest still supports rate
189	 * limiting and abuse triage and is useless for anything else. Stable across
190	 * restarts on purpose - a per-process salt would hand every address a fresh
191	 * bucket on each deploy. Each caller supplies its own salt so the two
192	 * features' digests are not interchangeable with each other.
193	 */
194	export function hashIp(salt: string, ip: string): string {
195	  return createHash("sha256").update(`${salt}:${ip}`).digest("hex");
196	}
197	
198	// -- Layer 1: in-process burst limiter ------------------------------------------
199	
200	export type BurstLimiter = { limited(key: string): boolean };
201	
202	/**
203	 * A bounded, in-process, sliding-window limiter. Each caller gets its own
204	 * instance (its own Map, its own limit/window/key cap) so the two features
205	 * cannot exhaust or reset each other's buckets.
206	 *
207	 * The map is bounded without ever letting a flood of unique keys wipe it:
208	 * expired entries go first, then the least recently active - an attacker's
209	 * own bucket is the most recently active, so it is the last thing evicted.
210	 * Deliberately NOT a wholesale `clear()`: that would be a documented way for
211	 * an attacker to reset the counter that is throttling them.
212	 */
213	export function createBurstLimiter(opts: {
214	  limit: number;
215	  windowMs: number;
216	  maxKeys: number;
217	}): BurstLimiter {
218	  const hits = new Map<string, number[]>();
219	
220	  function sweep(now: number): void {
221	    if (hits.size <= opts.maxKeys) return;
222	    for (const [key, arr] of hits) {
223	      if (arr.length === 0 || arr[arr.length - 1] <= now - opts.windowMs) hits.delete(key);
224	    }
225	    if (hits.size <= opts.maxKeys) return;
226	    const byLastSeen = [...hits.entries()].sort(
227	      (a, b) => a[1][a[1].length - 1] - b[1][b[1].length - 1],
228	    );
229	    for (const [key] of byLastSeen.slice(0, hits.size - opts.maxKeys)) hits.delete(key);
230	  }
231	
232	  return {
233	    limited(key: string): boolean {
234	      const now = Date.now();
235	      sweep(now);
236	      const recent = (hits.get(key) ?? []).filter((t) => t > now - opts.windowMs);
237	      if (recent.length >= opts.limit) {
238	        hits.set(key, recent);
239	        return true;
240	      }
241	      recent.push(now);
242	      hits.set(key, recent);
243	      return false;
244	    },
245	  };
246	}
247	
248	// -- Spam signal -----------------------------------------------------------------
249	
250	/**
251	 * Honeypot + timing verdict, shared because the contract is the same
252	 * wherever a control-field pair (`_gotcha`, `_t`) can appear: a field no
253	 * human can see is automation if filled in, and a submission completed
254	 * faster than `minFillMs` after the token's timestamp is very likely a
255	 * script. Advisory only - see the markup contract in lib/site-forms.ts.
256	 */
257	export function isLikelySpam(control: Record<string, string>, now: number, minFillMs: number): boolean {
258	  const trapped = (control._gotcha ?? "") !== "";
259	  const startedAt = Number(control._t ?? "");
260	  const tooFast =
261	    Number.isFinite(startedAt) &&
262	    startedAt > now - 24 * 60 * 60_000 &&
263	    startedAt <= now &&
264	    now - startedAt < minFillMs;
265	  return trapped || tooFast;
266	}
267	
268	// -- Host / origin checks ---------------------------------------------------------
269	
270	/**
271	 * Where "Back to the site" and a `_next` redirect point.
272	 *
273	 * On the branded subdomain the site is at `/`. On the staging path form
274	 * (staging.kodely.me/api/site/<slug>/ - see site-host.ts) it is one directory
275	 * deep, and a bare `/` would leave the customer's site entirely.
276	 */
277	export function siteBase(host: string, slug: string): string {
278	  return bareHost(host) === `${slug}.${SITES_BASE}` ? "/" : `/api/site/${slug}/`;
279	}
280	
281	/**
282	 * A browser always sends Origin on a cross-document POST, and for a form on
283	 * the site itself it is the site's own origin. Requiring it costs nothing and
284	 * turns away the simplest scripted floods and any other page trying to post
285	 * here on a visitor's behalf. It is FORGEABLE by anything that is not a
286	 * browser - this is a filter, not an authorisation check.
287	 */
288	export function originAllowed(req: Request, slug: string): boolean {
289	  const origin = req.headers.get("origin");
290	  if (!origin) return false;
291	  let originHost: string;
292	  try {
293	    originHost = new URL(origin).host;
294	  } catch {
295	    return false;
296	  }
297	  return siteHostAllowed(originHost, slug);
298	}
299	
300	/**
301	 * An optional post-submit destination, resolved against the site's own base.
302	 *
303	 * Only a path, never a URL: it must start with a single `/`, and
304	 * `//evil.example` (a protocol-relative URL, which is a cross-origin redirect
305	 * wearing a path's clothes) is rejected along with anything carrying a scheme
306	 * or a backslash. So this cannot become an open redirect, whatever the
307	 * builder emits.
308	 */
309	export function nextPath(control: Record<string, string>, base: string): string | null {
310	  const raw = control._next;
311	  if (!raw) return null;
312	  if (!/^\/[A-Za-z0-9\-._~!$&'()*+,;=:@%/?#]*$/.test(raw)) return null;
313	  if (raw.startsWith("//")) return null;
314	  return `${base}${raw.slice(1)}`;
315	}
316	
317	// -- HTML replies -------------------------------------------------------------
318	//
319	// A native form POST is a NAVIGATION: whatever comes back is what the visitor
320	// sees. So every reply here is a small, self-contained HTML page rather than
321	// JSON, and it echoes nothing that was submitted.
322	
323	export function escapeHtml(value: string): string {
324	  return value
325	    .replace(/&/g, "&amp;")
326	    .replace(/</g, "&lt;")
327	    .replace(/>/g, "&gt;")
328	    .replace(/"/g, "&quot;")
329	    .replace(/'/g, "&#39;");
330	}
331	
332	// Our own page, not the customer's, so it gets its own policy rather than the
333	// site's SANDBOX_CSP: it needs nothing but inline styles and must never be
334	// framed.
335	const REPLY_CSP =
336	  "default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'";
337	
338	export function htmlReply(status: number, title: string, body: string, backHref: string): Response {
339	  const html = `<!doctype html>
340	<html lang="en">
341	  <head>
342	    <meta charset="utf-8">
343	    <meta name="viewport" content="width=device-width,initial-scale=1">
344	    <meta name="robots" content="noindex">
345	    <title>${escapeHtml(title)}</title>
346	  </head>
347	  <body style="margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;background:#f6f7f8;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#111111;">
348	    <main style="max-width:420px;text-align:center;">
349	      <h1 style="margin:0 0 12px 0;font-size:20px;font-weight:600;letter-spacing:-0.01em;">${escapeHtml(title)}</h1>
350	      <p style="margin:0 0 20px 0;font-size:15px;line-height:1.6;color:#4b5563;">${escapeHtml(body)}</p>
351	      <a href="${escapeHtml(backHref)}" style="display:inline-block;padding:10px 18px;background:#111111;color:#ffffff;text-decoration:none;border-radius:8px;font-size:15px;font-weight:600;">Back to the site</a>
352	    </main>
353	  </body>
354	</html>
355	`;
356	  return new Response(html, {
357	    status,
358	    headers: {
359	      "Content-Type": "text/html; charset=utf-8",
360	      "Content-Security-Policy": REPLY_CSP,
361	      "X-Content-Type-Options": "nosniff",
362	      "Referrer-Policy": "no-referrer",
363	      "Cache-Control": "no-store",
364	    },
365	  });
366	}
367	
368	/**
369	 * The reply for "this site does not exist, is not published, or you are
370	 * asking from a host that may not serve it".
371	 *
372	 * One response for all three on purpose, and byte-compatible in meaning with
373	 * the GET handler's 404: a caller probing for which slugs exist, or which are
374	 * published, learns nothing from the difference.
375	 */
376	export function siteNotFound(): Response {
377	  return new Response("Site not found.", {
378	    status: 404,
379	    headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" },
380	  });
381	}
382

220	// package.json and tsconfig.json are here for the same family of reasons
221	// (lifecycle scripts, compiler plugins). The foundation supplies all of these
222	// already and the agent has no legitimate reason to touch them — the prompt
223	// has always told it not to. This makes that a rule instead of a request.
224	const PROTECTED_PATHS = new Set([
225	  "package.json",
226	  "package-lock.json",
227	  "tsconfig.json",
228	  "tsconfig.node.json",
229	]);
230	const PROTECTED_PATTERNS = [
231	  /^vite\.config\.[cm]?[jt]s$/i,
232	  /^postcss\.config\.[cm]?[jt]s$/i,
233	  /^tailwind\.config\.[cm]?[jt]s$/i,
234	  /^\./, // dotfiles: .npmrc, .env, .babelrc, and the asset catalogue
235	  /^node_modules\//i,
236	];
237	
238	/** True when writing this path would hand the agent server-side execution. */
239	export function isProtectedPath(path: string): boolean {
240	  if (PROTECTED_PATHS.has(path)) return true;
241	  return PROTECTED_PATTERNS.some((re) => re.test(path));
242	}
243	
244	/** Reject path traversal, absolute paths, and executable config before anything touches the DB. */
245	export function normalizePath(raw: string): string | null {
246	  const path = raw.trim().replace(/^\.?\//, "");
247	  if (!path || path.length > 200) return null;
248	  if (path.includes("..") || path.startsWith("/") || path.includes("\\")) return null;
249	  if (!/^[A-Za-z0-9._/-]+$/.test(path)) return null;
250	  if (isProtectedPath(path)) return null;
251	  return path;
252	}
253	
254	function describeFiles(files: FileMap): string {
255	  const paths = Object.keys(files);
256	  if (paths.length === 0) return "The project is empty — this is the first build.";
257	  return [
258	    "Current files in the project:",
259	    ...paths.map((p) => `\n--- ${p} ---\n${files[p]}`),
260	  ].join("\n");
261	}
262	
263	type RunOptions = {
264	  /** Prior turns, oldest first. */
265	  history: { role: "user" | "assistant"; content: string }[];
266	  request: string;
267	  files: FileMap;
268	  /** First build of a site vs a follow-up tweak — drives how hard we think. */
269	  kind: "create" | "edit";
270	  /** A reference image attached to this turn's request (vision input). */
271	  image?: { mediaType: string; data: string };
272	  /** A reference PDF attached to this turn's request (document input) — the
273	      base64 payload only, since `application/pdf` is the only media type the
274	      generate route accepts for this field. Mutually exclusive with `image`
275	      in practice (the composer's one attachment slot only ever fills one),
276	      but both are sent as separate content blocks below if somehow both are
277	      present, rather than one silently winning. */
278	  document?: { data: string };
279	  /** Applies the write; returning false rejects it (e.g. bad path). */
280	  onWrite: (path: string, content: string) => Promise<boolean>;
281	  onDelete: (path: string) => Promise<boolean>;
282	  /**
283	   * Aborted when the client disconnects (tab closed, network drop). Actually
284	   * cancels the in-flight Anthropic request instead of letting it run to
285	   * completion for nobody — a disconnect shouldn't mean paying full price for
286	   * a generation no one will ever see the result of.
287	   */
288	  signal?: AbortSignal;
289	  /**
290	   * Per-run engine override, for a gradual rollout onto the SDK.
291	   *
292	   * Strictly an UPGRADE path and never a downgrade: `KODELY_ENGINE=sdk` stays
293	   * an absolute pin (see runAgent below). That env var is an operator's
294	   * deliberate machine-level decision to stay off the metered key, and a
295	   * feature flag whose unset default is `false` must never be able to revoke
296	   * it silently — that inversion is how a flag becomes a second, contradictory
297	   * source of truth.
298	   *
299	   * Bucket this per USER, not per build. Splitting one person's builds across
300	   * both engines would contaminate any comparison between the two arms.
301	   */
302	  engine?: "api" | "sdk";
303	};
304	
305	/**
306	 * Runs the plan → generate → apply loop, streaming progress as it goes.
307	 * Token usage is accumulated across every turn so the caller can meter the
308	 * true cost of the build (including the repair turns, which we may not bill).
309	 */
310	// Which generation engine to use.
311	//   api (default) — metered Anthropic API via ANTHROPIC_API_KEY. Real cost,
312	//                   real usage telemetry, real credit charges.
313	//   sdk           — Claude Agent SDK on this machine's `claude setup-token`
314	//                   subscription login. No metered spend, so no cost data and
315	//                   0 credits charged. See lib/agent-sdk.ts for the caveats.
316	// Defaults to `api` so a fresh clone never silently runs on someone's personal
317	// subscription; the environment opts in.
318	export const ENGINE = process.env.KODELY_ENGINE === "sdk" ? "sdk" : "api";
319	
320	export async function* runAgent(opts: RunOptions): AsyncGenerator<AgentEvent> {
321	  // One place decides, and the env var wins. `KODELY_ENGINE=sdk` pins every
322	  // run to the SDK; when it is at its `api` default the caller may opt an
323	  // individual run in. Written as `||` rather than reading opts first so the
324	  // pin cannot be overridden by a caller — see the note on RunOptions.engine.
325	  const engine = ENGINE === "sdk" || opts.engine === "sdk" ? "sdk" : "api";
326	
327	  if (engine === "sdk") {
328	    // Deliberately no try/catch fallback to the API engine: if the SDK is not
329	    // authenticated this must fail loudly rather than quietly spend money on
330	    // the metered key the operator asked not to use.
331	    const { runAgentSdk } = await import("./agent-sdk");
332	    yield* runAgentSdk(opts, SYSTEM);
333	    return;
334	  }
335	
336	  const model = MODELS.builder;
337	  // Effort is the sharpest cost lever we have: a first build is a blank-page
338	  // design problem and earns `high`, while a targeted tweak lands the same
339	  // result at `medium` for a fraction of the thinking tokens.
340	  const effort = opts.kind === "create" ? EFFORT.create : EFFORT.edit;
341	
342	  const messages: Anthropic.MessageParam[] = [];
343	  for (const turn of opts.history) {
344	    messages.push({ role: turn.role, content: turn.content });
345	  }
346	  const requestText = `${describeFiles(opts.files)}\n\n--- Request ---\n${opts.request}`;
347	  if (opts.image || opts.document) {
348	    // Both blocks are built independently — in practice the composer's one
349	    // attachment slot never fills both at once, but nothing here assumes
350	    // that; either, or both, can be present and each gets its own real
351	    // content block plus its own line in the trailing note explaining what
352	    // it actually is.
353	    const content: Anthropic.ContentBlockParam[] = [];
354	    const notes: string[] = [];
355	
356	    if (opts.image) {
357	      content.push({
358	        type: "image",
359	        source: {
360	          type: "base64",
361	          media_type: opts.image.mediaType as "image/png" | "image/jpeg" | "image/webp",
362	          data: opts.image.data,
363	        },
364	      });
365	      notes.push("A reference image is attached above — use it as visual/style guidance for the site.");
366	    }
367	
368	    if (opts.document) {
369	      content.push({
370	        type: "document",
371	        source: {
372	          type: "base64",
373	          media_type: "application/pdf",
374	          data: opts.document.data,
375	        },
376	      });
377	      notes.push(
378	        "A reference PDF is attached above — read its actual text and layout for guidance on content and structure, not as a file to embed or link to in the site.",
379	      );
380	    }
381	
382	    content.push({
383	      type: "text",
384	      text: `${requestText}\n\n(${notes.join(" ")})`,
385	      cache_control: { type: "ephemeral" },
386	    });
387	
388	    messages.push({ role: "user", content });
389	  } else {
390	    // Cache breakpoint on the file tree.
391	    //
392	    // This message carries describeFiles() — every source file, in full. It is
